import {golfSurface,golfLaunch,golfStep,courseBunkers,BALL_HEIGHT} from '../shared/golf-physics.js';
import {visualKit,worldUV} from '../shared/visuals.js';
import {T,engine,batchStatic,box,sphere,cylinder,tree,ground,water,line,label} from '../shared/engine.js';
import {shell,load,save,toast,modal,lifecycle,tone,clamp,swingAccuracy,scoreGolf} from '../shared/core.js';
export function mount(){let state=load('golf',{x:0,z:4,strokes:0,done:false,hole:0,card:[]});if(state.done){const next=(state.hole??0)+1;state={x:0,z:4,strokes:0,done:false,hole:next<3?next:0,card:next<3?[...(state.card??[]),state.strokes]:[]};save('golf',state)}const courses=[{name:'Cypress Point',par:4,length:169,x:-9},{name:'Lighthouse Cove',par:3,length:104,x:6},{name:'The Dunes',par:4,length:192,x:-13}],hole=state.hole??0,course=courses[hole]||courses[0],zScale=course.length/169,wind=[{x:1.8,z:.3},{x:-1.2,z:.6},{x:2.4,z:-.6}][hole];shell('Fairway Coast',course.name.toUpperCase()+' · HOLE '+(hole+1)+' OF 3 · PAR '+course.par);const e=engine({sky:0x9bcbd5,fog:340}),s=e.scene;const visuals=visualKit(e,{coast:true});s.add(e.sun.target);visuals.surface(ground(s,0x496e43),'turf',5,0x6e844f);const sea=water(s,110,-100,150,700);sea.mesh.position.y=-1.1;sea.mesh.material.color.setHex(0x267f88);sea.mesh.material.opacity=.96;for(let i=0;i<36;i++){const z=30-i*9;visuals.boulder(s,40+Math.sin(i*1.6)*3,-2.6,z,6,4,7,i*.8);if(i%2===0){const x=-45-Math.sin(i)*6;visuals.boulder(s,x,-4,z,16,9,17,i);tree(s,x+3,z,.85)}}
function patch(points,color,y){const shape=new T.Shape();points.forEach(([x,z],i)=>i?shape.lineTo(x,-z):shape.moveTo(x,-z));shape.closePath();const m=new T.Mesh(new T.ShapeGeometry(shape,24),new T.MeshStandardMaterial({color,roughness:1}));m.rotation.x=-Math.PI/2;m.position.y=y;m.receiveShadow=true;s.add(m);visuals.surface(m,'turf',3,color);return m}
const left=[],right=[];for(let i=0;i<=40;i++){const z=-i*4.5*zScale,x=Math.sin(i*.12)*10,w=12+Math.sin(i*.2)*3;left.push([x-w,z]);right.unshift([x+w,z])}patch([...left,...right],0xc3d29e,.01);for(let i=0;i<40;i+=2){const r0=right[40-i],r1=right[39-i];patch([left[i],r0,r1,left[i+1]],0xb6c891,.018)}
const cup=new T.Vector3(course.x,.06,-course.length);const green=new T.Mesh(new T.ShapeGeometry(new T.Shape(Array.from({length:65},(_,i)=>{const a=i/64*Math.PI*2,r=12+Math.sin(a*3)*.65;return new T.Vector2(Math.cos(a)*r,Math.sin(a)*r)}))),new T.MeshStandardMaterial({color:0x9ebc75,roughness:1}));green.rotation.x=-Math.PI/2;green.position.copy(cup);green.position.y=.04;green.scale.set(1,1.25,1);green.receiveShadow=true;s.add(green);visuals.surface(green,'turf',1.7,0xd0dbb2);const apron=green.clone();apron.material=green.material.clone();apron.material.color.setHex(0x91ac72);apron.scale.multiplyScalar(1.1);apron.position.y=.026;s.add(apron);function bunker(x,z,rx,rz,seed){const inner=[],outer=[];for(let i=0;i<=64;i++){const a=i/64*Math.PI*2,r=1+.13*Math.sin(a*3+seed)+.06*Math.cos(a*5);inner.push(new T.Vector2(Math.cos(a)*rx*r,Math.sin(a)*rz*r));outer.push(new T.Vector2(Math.cos(a)*(rx+1.05)*r,Math.sin(a)*(rz+1.05)*r))}const floor=new T.Mesh(new T.ShapeGeometry(new T.Shape(inner)),visuals.materials.sand.clone());floor.rotation.x=-Math.PI/2;floor.position.set(x,.032,z);worldUV(floor.geometry,2.3);floor.receiveShadow=true;s.add(floor);const p=[],uv=[],ids=[];for(let i=0;i<=64;i++){for(const [j,v]of [outer[i],inner[i]].entries()){p.push(x+v.x,j?.033:.09,z-v.y);uv.push(v.x/3,v.y/3)}if(i<64){const k=i*2;ids.push(k,k+2,k+1,k+1,k+2,k+3)}}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(ids);g.computeVertexNormals();const lip=new T.Mesh(g,visuals.materials.turf.clone());lip.material.color.setHex(0x72884e);lip.receiveShadow=true;s.add(lip)}for(const b of courseBunkers(course))bunker(...b);
// A small lighthouse beyond the green gives the hole a readable coastal landmark.
const towerZ=-course.length-20;const tower=cylinder(s,31,6,towerZ,1.5,2.2,12,0xe7e2cb,32);cylinder(s,31,12.5,towerZ,1.8,1.8,1.7,0x344c51,24);cylinder(s,31,13.8,towerZ,0,2.4,1.5,0x385c5b,24);for(let i=0;i<8;i++){const a=i*Math.PI/4;box(s,31+Math.cos(a)*1.6,12.4,towerZ+Math.sin(a)*1.6,.12,1.5,.12,0xe8ddbd)}

cylinder(s,cup.x,.065,cup.z,.28,.28,.04,0x172c20,32);cylinder(s,cup.x,2,cup.z,.035,.035,4,0xeae7d7);const flag=new T.Mesh(new T.PlaneGeometry(1.3,.7,12,3),new T.MeshStandardMaterial({color:0xe39967,side:T.DoubleSide,roughness:.8}));flag.position.set(cup.x+.65,3.55,cup.z);s.add(flag);label(s,'0'+(hole+1),cup.x,5,cup.z,{size:4});for(let i=0;i<34;i++){const z=-i*6*zScale,x=i%2?-28-3*Math.sin(i):23+4*Math.cos(i);if(Math.abs(z+course.length)>13)tree(s,x,z,.7+(i%4)*.16,i%4===0)}for(let i=0;i<2;i++)box(s,i?2:-2,.15,6,.45,.3,.45,0xdddac7);
flag.userData.dynamic=true;batchStatic(s);let club='auto',pos=new T.Vector3(state.x,state.flight?(state.y??BALL_HEIGHT):BALL_HEIGHT,state.z),last=pos.clone(),vel=new T.Vector3(...(state.velocity??[0,0,0])),flight=state.flight??false,aim=0,power=.7,mode=0,phase=0,clock=0,overhead=false,settle=0;const ball=sphere(s,pos.x,pos.y,pos.z,.055,0xffffff);const aimLine=line(s,[[0,0,0],[0,0,0]],0xf3dfaf);const marker=cylinder(s,0,.03,0,.15,.15,.012,0xf1ddad);let life;document.querySelector('#controls').classList.add('golf-controls');document.querySelector('#controls').innerHTML=`<div class="control-note">Three taps: start, set power, strike.<br>Or flick upward on the course to shoot.</div><div class="control-panel"><label>AIM <input aria-label="Aim angle" id="aim" type="range" min="-50" max="50" value="0"></label><label>CLUB<select id="club" aria-label="Club"><option value="auto">Auto</option><option value="driver">Driver</option><option value="iron">Iron</option><option value="wedge">Wedge</option><option value="putter">Putter</option></select></label><button id="map">Map</button><div><div class="eyebrow" id="meterLabel">Ready to swing</div><div class="meter timing-track"><b></b><i id="fill"></i></div></div><button id="swing" class="primary">Swing</button></div>`;if(state.last)last.fromArray(state.last);const btn=document.querySelector('#swing');if(flight){btn.disabled=true;btn.textContent='Ball in flight'}document.querySelector('#aim').oninput=ev=>{aim=+ev.target.value*Math.PI/180};document.querySelector('#club').onchange=ev=>club=ev.target.value;document.querySelector('#map').onclick=()=>{overhead=!overhead};const distance=()=>Math.hypot(pos.x-cup.x,pos.z-cup.z);const direction=()=>new T.Vector3(cup.x-pos.x,0,cup.z-pos.z).normalize().applyAxisAngle(new T.Vector3(0,1,0),aim);
function persist(){state={x:pos.x,y:pos.y,z:pos.z,strokes:state.strokes,done:state.done,hole,card:state.card??[],velocity:vel.toArray(),flight,last:last.toArray()};save('golf',state)}
function shoot(p,acc){if(flight||state.done)return;last.copy(pos);state.strokes++;const d=distance(),dir=direction().applyAxisAngle(new T.Vector3(0,1,0),acc*.2);const selected=club==='auto'?(d<11?'putter':d<45?'wedge':d<100?'iron':'driver'):club;const launch=golfLaunch(selected,p,dir,golfSurface(pos.x,pos.z,course));vel.set(launch.vx,launch.vy,launch.vz);flight=true;settle=0;mode=0;btn.textContent='Ball in flight';btn.disabled=true;tone(260,.1,'triangle');}
btn.onclick=()=>{if(flight||state.done||life.paused())return;if(mode===0){mode=1;clock=0;btn.textContent='Set power'}else if(mode===1){power=phase;mode=2;clock=0;btn.textContent='Strike'}else shoot(power,swingAccuracy(phase))};
let drag;const down=ev=>{if(!flight&&!life.paused())drag={x:ev.clientX,y:ev.clientY,t:performance.now()}};const up=ev=>{if(!drag)return;const dy=drag.y-ev.clientY,dx=ev.clientX-drag.x;if(dy>35&&!flight&&!life.paused()){aim=clamp(-dx/350,-.8,.8);shoot(clamp(dy/260,.08,1),0)}drag=null};e.renderer.domElement.addEventListener('pointerdown',down);e.renderer.domElement.addEventListener('pointerup',up);e.renderer.domElement.addEventListener('pointercancel',()=>drag=null);
function finish(holed=false){flight=false;vel.set(0,0,0);pos.y=BALL_HEIGHT;if(holed){state.done=true;pos.copy(cup);tone(880,.5,'sine');persist();modal(scoreGolf(state.strokes,course.par),`<p>${course.name} complete in <strong>${state.strokes} strokes</strong>.</p><p>${[...(state.card??[]),state.strokes].map((n,i)=>courses[i].name+': '+n+' / par '+courses[i].par).join('<br>')}</p>`,[{text:hole<2?'Next hole':'Play the course again',action:()=>{save('golf',{x:0,z:4,strokes:0,done:false,hole:hole<2?hole+1:0,card:hole<2?[...(state.card??[]),state.strokes]:[]});location.reload()}},{text:'Return to Studio',action:()=>location.hash=''}])}else{persist();btn.disabled=false;btn.textContent='Swing';toast(distance()<15?'On the green · gentle strokes now':`${Math.round(distance())} m to the cup`)} }
life=lifecycle({pause:persist,reset:()=>save('golf',{x:0,z:4,strokes:0,done:false})});if(state.done){state={x:0,z:4,strokes:0,done:false,hole,card:state.card??[]};pos.set(0,BALL_HEIGHT,4)}if(!load('intro:golf',false))modal('A little room to swing',`<p>Aim with the slider. Tap <strong>Swing</strong> to start the power meter, tap to set power, then tap near the middle of the accuracy meter to hit straight.</p><p>Or flick upward on the course: longer flicks hit harder. Near the cup, shots automatically become putts. Map gives an overhead view. Auto selects a club for the distance; you can also choose one. Complete all three holes to fill your scorecard.</p>`,[{text:'On the tee',action:()=>save('intro:golf',true)}]);
e.start((dt,t)=>{sea.update(t);document.querySelector('.timing-track b').style.opacity=mode===2?'1':'0';const cloth=flag.geometry.attributes.position;for(let i=0;i<cloth.count;i++){const x=cloth.getX(i)+.65;cloth.setZ(i,Math.sin(t*3.5-x*4)*x*.11)}cloth.needsUpdate=true;flag.geometry.computeVertexNormals();const dir=direction();if(!life.paused()){if(mode){clock+=dt;phase=mode===1?(Math.sin(clock*2.3-Math.PI/2)+1)/2:(Math.sin(clock*3.1)+1)/2;document.querySelector('#fill').style.width=phase*100+'%';document.querySelector('#fill').style.background=mode===2&&Math.abs(phase-.5)<.09?'#93dfad':'#e7c285';document.querySelector('#meterLabel').textContent=mode===1?`Power ${Math.round(phase*100)}%`:'Accuracy · stop at 50%'}if(flight){const next=golfStep({x:pos.x,y:pos.y,z:pos.z,vx:vel.x,vy:vel.y,vz:vel.z},dt,{surface:(x,z)=>golfSurface(x,z,course),cup,wind});pos.set(next.x,next.y,next.z);vel.set(next.vx,next.vy,next.vz);if(pos.x>39||Math.abs(pos.x)>100||pos.z<-250||pos.z>55){state.strokes++;pos.copy(last);finish();toast('Out of bounds · one penalty stroke')}else if(next.holed||next.stopped)finish(next.holed)}}ball.position.copy(pos);e.sun.position.copy(pos).add(new T.Vector3(-35,65,25));e.sun.target.position.copy(pos);marker.position.set(pos.x,.05,pos.z);marker.visible=!flight&&!state.done;const pts=[pos.clone(),pos.clone().addScaledVector(dir,Math.min(distance(),12))];pts.forEach(p=>p.y=.3);aimLine.geometry.setFromPoints(pts);aimLine.visible=!flight;const portrait=innerHeight>innerWidth,target=pos.clone().addScaledVector(dir,overhead?0:Math.min(distance()*.5,12));let cam=overhead?pos.clone().add(new T.Vector3(0,90,25)):pos.clone().addScaledVector(dir,distance()<15?(portrait?-9:-7):(portrait?-19:-16)).add(new T.Vector3(0,distance()<15?(portrait?6:4):(portrait?9:6),0));if(flight)cam=pos.clone().add(new T.Vector3(10,12,19));e.camera.position.lerp(cam,1-Math.exp(-dt*4));e.camera.lookAt(target);document.querySelector('#stat').textContent=`${golfSurface(pos.x,pos.z,course).toUpperCase()} · Wind ${Math.round(Math.hypot(wind.x,wind.z)*3.6)} km/h ${wind.x>0?'→':'←'} · ${state.strokes} strokes  ·  ${Math.round(distance())} m  ·  ${club==='auto'?(distance()<11?'Putter':distance()<45?'Wedge':distance()<100?'Iron':'Driver'):club} · Hole ${hole+1}/3`});return {dispose(){persist();life.dispose();visuals.dispose();e.dispose()}}}
